package com.aoo.bcg.poker;
import java.util.*;
/** Generic follow-category, trick-resolution and scoring engine. */
public final class TrickTakingEngine{
 public TrickTakingState play(TrickTakingState state,int seat,int card,TrickTakingRules rules){if(state.finished()||seat!=state.currentSeat())throw new IllegalStateException("not current seat");List<Integer> original=state.hands().get(seat);if(!original.contains(card))throw new IllegalStateException("card not in hand");if(!state.trick().isEmpty()){int lead=rules.category(state.trick().get(state.leaderSeat()));if(original.stream().anyMatch(value->rules.category(value)==lead)&&rules.category(card)!=lead)throw new IllegalStateException("must follow lead category");}Map<Integer,List<Integer>> hands=new LinkedHashMap<>(state.hands());List<Integer> hand=new ArrayList<>(original);hand.remove(Integer.valueOf(card));hands.put(seat,hand);Map<Integer,Integer> trick=new LinkedHashMap<>(state.trick());trick.put(seat,card);List<Integer> seats=hands.keySet().stream().sorted().toList();if(trick.size()<seats.size())return new TrickTakingState(hands,next(seats,seat),state.leaderSeat(),trick,state.scores(),false);int winner=rules.winner(trick,state.leaderSeat());Map<Integer,Integer> scores=new HashMap<>(state.scores());scores.merge(winner,rules.points(trick),Math::addExact);boolean finished=hands.values().stream().allMatch(List::isEmpty);return new TrickTakingState(hands,winner,winner,Map.of(),scores,finished);}
 private static int next(List<Integer> seats,int seat){return seats.get((seats.indexOf(seat)+1)%seats.size());}
}
